module adder_bcd(A,B,Cin,Sum,Cout);
	input [3:0] A,B;
	input Cin;
	output reg [3:0] Sum;
	output reg Cout;
	wire [4:0] temp;
	assign temp = A+B+Cin;

	always@(*) begin
		if(temp > 9) begin
			Sum = temp+6;
			Cout = 1;
		end
		else begin
			Sum = temp;
			Cout = 0;
		end
	end

endmodule
